// The Spells tab's "All spells" view: a class's level 1-60 spells
// (src/data/spells-1-60.json, generated by scripts/gen-spells-1-60.sh) on top
// of the fixed 61-65 list. Personal tracking only — /spells, its grid and the
// officer hide settings stay on 61-65. Server-only: import it from pages and
// actions, never from a client component, so the ~150 KB list stays out of
// the browser bundle (the page passes the one class's slice down).

import lowSpellsData from "@/data/spells-1-60.json";

import { spellsForClass, type ClassSpell, type Spell } from "./index";

const LOW_SPELLS: readonly Spell[] = lowSpellsData as Spell[];

const lowCache = new Map<number, ClassSpell[]>();

// A class's level 1-60 spells, level then name.
export function lowSpellsForClass(classId: number): ClassSpell[] {
  let list = lowCache.get(classId);
  if (!list) {
    list = [];
    for (const s of LOW_SPELLS) {
      const c = s.classes.find((k) => k.classId === classId);
      if (c) list.push({ spellId: s.spellId, name: s.name, level: c.level, scrollItemId: s.scrollItemId });
    }
    list.sort((a, b) => a.level - b.level || a.name.localeCompare(b.name));
    lowCache.set(classId, list);
  }
  return list;
}

// Every spell a class can scribe, 1-65 — what the spellbook import matches
// against and what a Spells tab checkbox may set. The generators guarantee a
// class never gets the same spell from both files.
export function allSpellsForClass(classId: number): ClassSpell[] {
  return [...lowSpellsForClass(classId), ...spellsForClass(classId)];
}
